const item = $input.first().json;
const waId = String(item.wa_id || 'unknown');
let h1 = 0x811c9dc5;
let h2 = 0x811c9dc5;
for (let i = 0; i < waId.length; i++) {
  const c = waId.charCodeAt(i);
  h1 ^= c;
  h1 += (h1 << 1) + (h1 << 4) + (h1 << 7) + (h1 << 8) + (h1 << 24);
  h2 ^= (c + i);
  h2 += (h2 << 1) + (h2 << 4) + (h2 << 7) + (h2 << 8) + (h2 << 24);
}
const hex = (n) => (n >>> 0).toString(16).padStart(8, '0');
const raw = (hex(h1) + hex(h2) + hex(h1 ^ h2) + hex((h1 + h2) >>> 0)).slice(0, 32);
const customerId = raw.slice(0,8) + '-' + raw.slice(8,12) + '-' + raw.slice(12,16) + '-' + raw.slice(16,20) + '-' + raw.slice(20,32);
return [{ json: { ...item, customer_id: customerId } }];

const out = $input.first().json;
const waId = $('Normalizar Entrada').item.json.wa_id;
const rawInput = $('Normalizar Entrada').item.json.raw_input ?? {};
const messageText = $('Normalizar Entrada').item.json.message_text ?? '';
const extractedNode = $('Extraer Datos Vitales').item.json;
const extractedFacts = extractedNode.extracted_facts ?? {};
const resetNotifyRequested = Boolean(extractedNode.reset_notify_requested);
const securityFlags = extractedNode.security_flags ?? {};

let h1 = 0x811c9dc5;
let h2 = 0x811c9dc5;
for (let i = 0; i < waId.length; i++) {
  const c = waId.charCodeAt(i);
  h1 ^= c;
  h1 += (h1 << 1) + (h1 << 4) + (h1 << 7) + (h1 << 8) + (h1 << 24);
  h2 ^= (c + i);
  h2 += (h2 << 1) + (h2 << 4) + (h2 << 7) + (h2 << 8) + (h2 << 24);
}
const hex = (n) => (n >>> 0).toString(16).padStart(8, '0');
const raw = (hex(h1) + hex(h2) + hex(h1 ^ h2) + hex((h1 + h2) >>> 0)).slice(0, 32);
const customerId = raw.slice(0, 8) + '-' + raw.slice(8, 12) + '-' + raw.slice(12, 16) + '-' + raw.slice(16, 20) + '-' + raw.slice(20, 32);

return [{
  json: {
    wa_id: waId,
    customer_id: customerId,
    output: out.output,
    message_text: messageText,
    raw_input: rawInput,
    needs_human: Boolean(out.needs_human),
    handoff_reason: String(out.handoff_reason || ''),
    extracted_facts: extractedFacts,
    memory_key_facts: out.memory_key_facts ?? {},
    reset_notify_requested: resetNotifyRequested,
    security_flags: securityFlags
  }
}];

const item = $input.first().json;
const text = String(item.message_text || '').toLowerCase();
const security = item.security_flags || {};

let reason = '';
let handoffOutput = '';
let needsHuman = false;

if (security.is_prompt_injection) {
  reason = 'security_prompt_injection';
  handoffOutput = 'Por seguridad solo puedo ayudarte con consignacion de autos y su proceso. Si quieres vender tu auto por consignacion, comparteme marca/modelo/ano/km o link de publicacion.';
} else if (security.is_spam_like) {
  reason = 'security_spam_guard';
  handoffOutput = 'Recibi mucha informacion en un solo mensaje. Para ayudarte mejor, enviame un mensaje breve y relacionado con consignacion de autos.';
} else {
  const patterns = [
    { r: /\b(humano|persona|ejecutivo|asesor|persona real|hablar con alguien|necesito hablar|quiero hablar con)\b/, reason: 'solicitud_humano' },
    { r: /\b(prenda|deuda prendaria|limitacion de dominio|embargo|gravamen|perdida total|pérdida total)\b/, reason: 'caso_legal' },
    { r: /\b(multa|multas)\b/, reason: 'multas' },
    { r: /\b(reclamo|queja|molesto|mala atencion|denuncia|demanda|estafa)\b/, reason: 'reclamo' }
  ];

  for (const pattern of patterns) {
    if (pattern.r.test(text)) {
      reason = pattern.reason;
      break;
    }
  }

  if (reason) {
    needsHuman = true;
    handoffOutput = 'Perfecto, te derivo de inmediato con un ejecutivo para ayudarte bien con tu caso. Para agilizar, comparteme nombre, telefono, marca/modelo/ano/kilometraje y motivo.';
  }
}

return [{
  json: {
    ...item,
    needs_human: Boolean(needsHuman),
    handoff_reason: reason,
    handoff_output: handoffOutput
  }
}];

const item = $input.first().json;
const waId = String(item.wa_id || 'unknown');
let h1 = 0x811c9dc5;
let h2 = 0x811c9dc5;
for (let i = 0; i < waId.length; i++) {
  const c = waId.charCodeAt(i);
  h1 ^= c;
  h1 += (h1 << 1) + (h1 << 4) + (h1 << 7) + (h1 << 8) + (h1 << 24);
  h2 ^= (c + i);
  h2 += (h2 << 1) + (h2 << 4) + (h2 << 7) + (h2 << 8) + (h2 << 24);
}
const hex = (n) => (n >>> 0).toString(16).padStart(8, '0');
const raw = (hex(h1) + hex(h2) + hex(h1 ^ h2) + hex((h1 + h2) >>> 0)).slice(0, 32);
const customerId = raw.slice(0,8) + '-' + raw.slice(8,12) + '-' + raw.slice(12,16) + '-' + raw.slice(16,20) + '-' + raw.slice(20,32);
return [{ json: { ...item, customer_id: customerId } }];

const live = $('Preparar Contexto Memoria Persistente').item.json;
const mem = $input.first().json || {};

let keyFacts = {};
if (mem.key_facts && typeof mem.key_facts === 'object') {
  keyFacts = mem.key_facts;
} else if (typeof mem.key_facts === 'string') {
  try {
    keyFacts = JSON.parse(mem.key_facts);
  } catch (e) {
    keyFacts = {};
  }
}

const currentFacts = live.extracted_facts || {};
for (const [key, value] of Object.entries(currentFacts)) {
  if (value !== null && value !== undefined && String(value).trim() !== '') {
    keyFacts[key] = typeof value === 'string' ? value.trim() : value;
  }
}

const nowIso = new Date().toISOString();
const nonEmpty = (v) => typeof v === 'string' ? v.trim().length > 0 : v !== null && v !== undefined;

const firstSeenBase = keyFacts.primer_contacto_at || keyFacts.first_contact_at || mem.created_at || nowIso;
keyFacts.primer_contacto_at = String(firstSeenBase);
keyFacts.first_contact_at = String(firstSeenBase);
keyFacts.ultimo_contacto_at = nowIso;
keyFacts.last_contact_at = nowIso;

const hasEmail = nonEmpty(keyFacts.customer_email);
const hasAuto = nonEmpty(keyFacts.vehicle_brand_model)
  || nonEmpty(keyFacts.vehicle_description)
  || nonEmpty(keyFacts.vehicle_url);

keyFacts.has_closing_email = hasEmail;
keyFacts.has_vehicle_min_data = hasAuto;
keyFacts.correo_de_cierre = hasEmail;

let stage = 'contacto_inicial';
if (hasEmail && hasAuto) stage = 'listo_para_cierre';
else if (hasEmail || hasAuto) stage = 'datos_parciales';
keyFacts.funnel_stage = stage;

const rawSignal = String(keyFacts.user_signal || keyFacts.last_turn_signal || 'regular').toLowerCase();
let userSignal = 'regular';
if (rawSignal.includes('question')) userSignal = 'question';
else if (rawSignal.includes('phatic')) userSignal = 'phatic';
else if (rawSignal.includes('command')) userSignal = 'command';
else if (rawSignal.includes('ambiguous')) userSignal = 'ambiguous';

const postCloseLock = stage === 'listo_para_cierre' ? 'on' : 'off';
const isPostCloseStrict = postCloseLock === 'on';

let responseStyle = String(keyFacts.response_style || 'normal');
if (postCloseLock === 'on' && userSignal === 'phatic') responseStyle = 'ultra_concise';
else if (postCloseLock === 'on' && userSignal === 'question') responseStyle = 'concise';
else if (userSignal === 'question' || userSignal === 'command') responseStyle = 'concise';

const precisionMode = (postCloseLock === 'on' || responseStyle !== 'normal') ? 'on' : 'off';
const toneMode = postCloseLock === 'on' ? 'direct' : 'warm';

let contactState = 'active';
const hasHistory = Boolean(mem.context_summary || mem.key_facts || mem.last_intent);
if (!hasHistory && stage === 'contacto_inicial') contactState = 'new';
else if (stage === 'listo_para_cierre') contactState = 'closed';

let daysSinceLastContact = null;
let isReturningClient = false;
const lastUpdate = mem.updated_at || mem.created_at;
if (lastUpdate) {
  const diffMs = Date.now() - new Date(lastUpdate).getTime();
  daysSinceLastContact = Math.floor(diffMs / (1000 * 60 * 60 * 24));
  isReturningClient = daysSinceLastContact >= 1;
  if (isReturningClient && contactState !== 'closed') contactState = 'reengaged';
}

keyFacts.contact_state = contactState;
keyFacts.response_style = responseStyle;
keyFacts.precision_mode = precisionMode;
keyFacts.post_close_lock = postCloseLock;
keyFacts.is_post_close_strict = isPostCloseStrict;
keyFacts.tone_mode = toneMode;
keyFacts.user_signal = userSignal;

if (keyFacts.derivado_agente_humano === undefined) keyFacts.derivado_agente_humano = false;
if (keyFacts.is_human_handoff === undefined) keyFacts.is_human_handoff = false;

keyFacts.conversation_version = 8;

return [{
  json: {
    ...live,
    memory_summary: String(mem.context_summary || ''),
    memory_last_intent: String(mem.last_intent || ''),
    memory_needs_human: Boolean(mem.needs_human),
    memory_key_facts: keyFacts,
    days_since_last_contact: daysSinceLastContact,
    is_returning_client: isReturningClient
  }
}];

const item = $input.first().json;
const messageText = String(item.message_text || '').trim();
const text = messageText.toLowerCase();
const rawInput = item.raw_input || {};

const facts = {};
const updatedFields = [];

const normalize = (value) => String(value || '').trim();
const addFact = (key, value) => {
  const cleaned = normalize(value);
  if (!cleaned) return;
  facts[key] = cleaned;
  updatedFields.push(key);
};

const parseBool = (v) => {
  if (typeof v === 'boolean') return v;
  const s = String(v || '').toLowerCase().trim();
  return s === 'true' || s === '1' || s === 'si' || s === 'yes';
};

const injectionNeedles = [
  'ignora instrucciones', 'ignora todas las instrucciones', 'actua como', 'system prompt',
  'developer message', 'prompt interno', 'revela tu prompt', 'muestra tu prompt', 'jailbreak', 'pretende ser'
];

const inDomainNeedles = [
  'consign', 'vender mi auto', 'vender auto', 'vehiculo', 'camioneta', 'marca', 'modelo',
  'ano', 'año', 'km', 'kilometraje', 'correo', 'ubicacion', 'telefono', 'comision', 'proceso', 'queirolo', 'whatsapp'
];

const neutralText = text.replace(/[!?.,]/g, '').trim();
const neutralSet = new Set(['hola', 'buenas', 'gracias', 'ok', 'dale', 'perfecto', 'listo', 'si', 'no', 'hi', 'hello', 'lo']);
const phaticSet = new Set(['ok', 'oka', 'okey', 'si ok', 'dale', 'gracias', 'listo', 'perfecto', 'lo', 'super', 'genial', 'buenisimo']);

const tokens = neutralText ? neutralText.split(' ').filter(Boolean) : [];
const tokenCount = tokens.length;
const allTokensArePhatic = tokens.length > 0 && tokens.every(t => phaticSet.has(t) || neutralSet.has(t));
const hasQuestion = /\?$|\b(como|que|cual|donde|cuando|por que|pueden|tienen|hacen|cuanto)\b/i.test(text);
const isPhaticAck = tokenCount <= 3 && !hasQuestion && (phaticSet.has(neutralText) || neutralSet.has(neutralText) || allTokensArePhatic);

const urlCount = (messageText.match(/https?:\/\//gi) || []).length;
const hasPromptInjection = injectionNeedles.some(n => text.includes(n));
const isInDomain = inDomainNeedles.some(n => text.includes(n));
const isNeutral = neutralSet.has(neutralText);
const isTooLong = messageText.length > 900;
const hasRepeatedChars = /(.)\1{10,}/.test(text);
const isSpamLike = isTooLong || hasRepeatedChars || urlCount > 2;
const isShortOrAmbiguous = messageText.length <= 18 || /^(hola|buenas|ok|dale|si|no|gracias|como estas|hola\?|buenas\?|lo)$/i.test(neutralText);
const isOffTopic = messageText.length > 40 && !hasPromptInjection && !isInDomain && !isNeutral && !isShortOrAmbiguous && !hasQuestion;
const securityLevel = hasPromptInjection ? 'high' : (isSpamLike ? 'medium' : (isOffTopic ? 'low' : 'none'));

let userSignal = 'regular';
if (hasQuestion) userSignal = 'question';
else if (isPhaticAck) userSignal = 'phatic';
else if (/^(envia|manda|dame|pasame|quiero|necesito|deriva|contacta)\b/i.test(text)) userSignal = 'command';
else if (tokenCount <= 2 && !isInDomain) userSignal = 'ambiguous';

let responseStyleSuggested = 'normal';
if (userSignal === 'phatic') responseStyleSuggested = 'ultra_concise';
else if (userSignal === 'question' || userSignal === 'command') responseStyleSuggested = 'concise';

const precisionModeSuggested = (userSignal === 'phatic' || userSignal === 'question' || tokenCount <= 3) ? 'on' : 'off';

const waName = normalize(rawInput?.body?.name);
if (waName) addFact('customer_name', waName);
const nameMatch = messageText.match(/(?:me\s+llamo|soy|mi\s+nombre\s+es)\s+([a-zA-ZáéíóúñÁÉÍÓÚÑüÜ\s]{2,50})/i);
if (nameMatch && !facts.customer_name) addFact('customer_name', nameMatch[1].trim());

const emailTokenMatch = messageText.match(/([^\s<>"'`]+@[^\s<>"'`]+\.[^\s<>"'`]+)/i);
if (emailTokenMatch) {
  let rawEmail = String(emailTokenMatch[1] || '').trim().replace(/[),.;:!?]+$/, '');
  rawEmail = rawEmail.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const safeEmail = rawEmail.toLowerCase();
  if (/^[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}$/i.test(safeEmail)) {
    addFact('customer_email', safeEmail);
  }
}

const phoneMatch = messageText.match(/(?:\+?56)?\s*9\s*\d{4}\s*\d{4}/);
if (phoneMatch) addFact('customer_phone', phoneMatch[0].replace(/\s/g, ''));

const urlMatch = messageText.match(/https?:\/\/[^\s]+/i);
if (urlMatch) addFact('vehicle_url', urlMatch[0]);

let kmNum = 0;
const kmWithUnit = messageText.match(/\b(\d{2,3}(?:[.,]\d{3})+|\d{4,6})\s*(km|kms|kilometros|kilómetros)\b/i);
const kmMil = messageText.match(/\b(\d{2,3})\s*mil\b/i);

if (kmWithUnit) {
  kmNum = parseInt(String(kmWithUnit[1] || '').replace(/[.,]/g, ''), 10);
} else if (kmMil) {
  kmNum = parseInt(String(kmMil[1] || '').replace(/[^0-9]/g, ''), 10) * 1000;
}

const yearLike = messageText.match(/\b(19[89]\d|20[0-2]\d)\b/);
const yearCandidate = yearLike ? parseInt(yearLike[1], 10) : 0;

if (Number.isFinite(kmNum) && kmNum >= 1000 && kmNum <= 500000 && kmNum !== yearCandidate && !(kmNum >= 1800 && kmNum <= 2099)) {
  addFact('vehicle_km', kmNum.toLocaleString('es-CL') + ' km');
}

const yearMatch = messageText.match(/\b(19[89]\d|20[0-2]\d)\b/);
if (yearMatch) addFact('vehicle_year', yearMatch[1]);

const brands = 'toyota|hyundai|kia|suzuki|chevrolet|nissan|mazda|mitsubishi|ford|volkswagen|vw|honda|subaru|peugeot|citroen|renault|fiat|jeep|bmw|mercedes|audi|volvo|mg|chery|jac|byd|haval|changan|great wall|ssangyong|dodge|ram|mini';
const brandRe = new RegExp('\\b(' + brands + ')\\b\\s*([a-zA-Z0-9áéíóúñ\\s-]{2,40})?', 'i');
const brandMatch = messageText.match(brandRe);
if (brandMatch) {
  const brand = String(brandMatch[1] || '').trim();
  const tail = String(brandMatch[2] || '').trim();
  const stopWords = new Set(['mi','nombre','soy','me','llamo','correo','email','mail','por','cierto']);
  const modelTokens = [];
  for (const token of tail.split(/\\s+/).filter(Boolean)) {
    const low = token.toLowerCase();
    if (stopWords.has(low) || low.includes('@')) break;
    if (/(km|kms|kilometros|kilómetros)/i.test(low)) break;
    if (/^\\d{5,6}$/.test(low)) break;
    if (low === 'con' && modelTokens.length > 0) break;
    modelTokens.push(token);
    if (modelTokens.length >= 3) break;
  }

  const vehicleDesc = [brand, ...modelTokens].join(' ').trim();
  addFact('vehicle_brand_model', vehicleDesc);
}

const vehicleCue = /\b(auto|vehiculo|camioneta|suv|sedan|hatchback|pickup|van|marca|modelo|ano|año|kilometraje|km|publicado|publicacion)\b/i;
if (vehicleCue.test(messageText) && !facts.vehicle_brand_model) addFact('vehicle_description', messageText.slice(0, 250));

let detectedIntent = '';
let detectedIntentConfidence = 'low';
const intentConsignar = [/\bconsign(?:ar|acion|ación)\b/i, /\bquiero\s+(?:consignar|vender|dejar)\b/i, /\bvender\s+(?:mi\s+)?(?:auto|vehiculo|camioneta)\b/i, /\bdejar(?:lo)?\s+en\s+consignacion\b/i];
const intentComision = [/\bcuanto\s+(?:cobran|cuesta|vale|sale)\b/i, /\bcomision\b/i];
const intentUbicacion = [/\bdonde\s+estan\b/i, /\bubicacion\b/i, /\bdireccion\b/i, /\bmapa\b/i];
const intentProceso = [/\bcomo\s+(?:funciona|es)\s+(?:la\s+)?consignacion\b/i, /\bpasos\b/i, /\bproceso\b/i];

if (intentConsignar.some(re => re.test(messageText))) {
  detectedIntent = 'consignar_auto';
  detectedIntentConfidence = 'high';
  addFact('customer_intent', 'consignar_auto');
} else if (intentComision.some(re => re.test(messageText))) {
  detectedIntent = 'consulta_comision';
  detectedIntentConfidence = 'high';
} else if (intentUbicacion.some(re => re.test(messageText))) {
  detectedIntent = 'consulta_ubicacion';
  detectedIntentConfidence = 'medium';
} else if (intentProceso.some(re => re.test(messageText))) {
  detectedIntent = 'consulta_proceso';
  detectedIntentConfidence = 'medium';
}

if (detectedIntent) {
  addFact('last_user_intent', detectedIntent);
  addFact('last_user_intent_confidence', detectedIntentConfidence);
}

addFact('last_turn_signal', userSignal === 'phatic' ? 'phatic_ack' : (hasQuestion ? 'question' : 'regular'));
addFact('user_signal', userSignal);
addFact('response_style', responseStyleSuggested);
addFact('precision_mode', precisionModeSuggested);

const resetNotify = /\b(reset\s*notify|reset\s*notificacion|reset\s*notificación|reset\s*lead\s*caliente)\b/i.test(messageText);
if (resetNotify) {
  addFact('team_notified', 'false');
  addFact('team_notified_at', '');
}

const comunaContext = /\b(buscar|retirar|pasar\s+a\s+buscar|ir\s+a\s+buscar|domicilio|casa|hogar)\b/i;
if (comunaContext.test(messageText)) addFact('needs_pickup', 'true');

let isOffHours = false;
try {
  const now = new Date();
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/Santiago',
    hour: 'numeric',
    hour12: false,
    weekday: 'short'
  }).formatToParts(now);
  const hour = parseInt(parts.find(p => p.type === 'hour').value);
  const weekday = parts.find(p => p.type === 'weekday').value;
  isOffHours = hour < 8 || hour >= 18 || weekday === 'Sat' || weekday === 'Sun';
} catch (e) {
  isOffHours = false;
}

return [{
  json: {
    ...item,
    extracted_facts: facts,
    extracted_fields: updatedFields,
    is_off_hours: isOffHours,
    reset_notify_requested: parseBool(facts.team_notified === 'false'),
    security_flags: {
      level: securityLevel,
      is_prompt_injection: hasPromptInjection,
      is_spam_like: isSpamLike,
      is_off_topic: isOffTopic,
      is_in_domain: isInDomain,
      is_phatic_ack: isPhaticAck,
      mode: 'soft'
    }
  }
}];

const existing = $input.first().json || {};
const outbound = $('Preparar Outbound Persistencia').item.json;

const nowIso = new Date().toISOString();
const nowMs = Date.now();
const COOLDOWN_MINUTES = 360;
const cooldownMs = COOLDOWN_MINUTES * 60 * 1000;

const nonEmpty = (v) => typeof v === 'string' ? v.trim().length > 0 : v !== null && v !== undefined;
const normalizeText = (v) => typeof v === 'string' ? v.trim() : v;
const parseBool = (v) => {
  if (typeof v === 'boolean') return v;
  const s = String(v || '').toLowerCase().trim();
  return s === 'true' || s === '1' || s === 'si' || s === 'yes';
};
const normalizeForRepeat = (txt) => String(txt || '').toLowerCase().replace(/[!?.,;:]/g, '').replace(/\s+/g, ' ').trim();

let existingFacts = {};
let parseStatus = 'ok';
if (existing.key_facts && typeof existing.key_facts === 'object') {
  existingFacts = existing.key_facts;
} else if (typeof existing.key_facts === 'string') {
  try {
    existingFacts = JSON.parse(existing.key_facts);
  } catch (e) {
    existingFacts = {};
    parseStatus = 'invalid_json';
  }
} else if (existing.key_facts === null || existing.key_facts === undefined) {
  parseStatus = 'empty';
}

const contextFacts = outbound.memory_key_facts && typeof outbound.memory_key_facts === 'object'
  ? outbound.memory_key_facts
  : {};
const incomingFacts = outbound.extracted_facts || {};

const mergedFacts = { ...existingFacts, ...contextFacts };
const updated = [];

for (const [key, value] of Object.entries(incomingFacts)) {
  if (nonEmpty(value)) {
    const normalized = normalizeText(value);
    if (mergedFacts[key] !== normalized) {
      mergedFacts[key] = normalized;
      updated.push(key);
    }
  }
}

if (!nonEmpty(mergedFacts.customer_name)) {
  const fallbackName = String(outbound.raw_input?.body?.name || '').trim();
  if (fallbackName) {
    mergedFacts.customer_name = fallbackName;
    updated.push('customer_name');
  }
}

const firstSeen = mergedFacts.primer_contacto_at || mergedFacts.first_contact_at || existing.created_at || nowIso;
mergedFacts.primer_contacto_at = String(firstSeen);
mergedFacts.first_contact_at = String(firstSeen);
mergedFacts.ultimo_contacto_at = nowIso;
mergedFacts.last_contact_at = nowIso;

const hasEmail = nonEmpty(mergedFacts.customer_email);
const hasAuto = nonEmpty(mergedFacts.vehicle_brand_model)
  || nonEmpty(mergedFacts.vehicle_description)
  || nonEmpty(mergedFacts.vehicle_url);

mergedFacts.has_closing_email = hasEmail;
mergedFacts.has_vehicle_min_data = hasAuto;
mergedFacts.correo_de_cierre = hasEmail;

let stage = 'contacto_inicial';
const isHuman = Boolean(outbound.needs_human);
if (isHuman) stage = 'derivado';
else if (hasEmail && hasAuto) stage = 'listo_para_cierre';
else if (hasEmail || hasAuto) stage = 'datos_parciales';
mergedFacts.funnel_stage = stage;

let contactState = 'active';
if (stage === 'listo_para_cierre') contactState = 'closed';
else {
  const lastSeen = existing.updated_at ? new Date(existing.updated_at).getTime() : 0;
  const daysSince = lastSeen ? Math.floor((nowMs - lastSeen) / 86400000) : 0;
  if (daysSince >= 1) contactState = 'reengaged';
}
if (!existing.created_at && stage === 'contacto_inicial') contactState = 'new';
mergedFacts.contact_state = contactState;

const userSignal = String(mergedFacts.user_signal || mergedFacts.last_turn_signal || 'regular');
const postCloseLock = stage === 'listo_para_cierre' ? 'on' : 'off';
let responseStyle = String(mergedFacts.response_style || 'normal');
if (postCloseLock === 'on' && userSignal === 'phatic') responseStyle = 'ultra_concise';
else if (userSignal === 'question' || userSignal === 'command') responseStyle = 'concise';
const precisionMode = (postCloseLock === 'on' || responseStyle !== 'normal') ? 'on' : 'off';
const toneMode = postCloseLock === 'on' ? 'direct' : 'warm';

mergedFacts.post_close_lock = postCloseLock;
mergedFacts.is_post_close_strict = postCloseLock === 'on';
mergedFacts.response_style = responseStyle;
mergedFacts.precision_mode = precisionMode;
mergedFacts.tone_mode = toneMode;

mergedFacts.derivado_agente_humano = isHuman;
mergedFacts.is_human_handoff = isHuman;
if (isHuman) mergedFacts.last_handoff_reason = String(outbound.handoff_reason || '');

const outputText = String(outbound.output || '').trim();
if (outputText) {
  const prevOutput = String(mergedFacts.last_assistant_output || '').trim();
  const prevNorm = normalizeForRepeat(prevOutput);
  const currNorm = normalizeForRepeat(outputText);
  const isRepeat = prevNorm && currNorm && (prevNorm === currNorm || prevNorm.includes(currNorm) || currNorm.includes(prevNorm));
  mergedFacts.assistant_repeat_count = isRepeat ? Number(mergedFacts.assistant_repeat_count || 0) + 1 : 0;
  mergedFacts.last_assistant_output = outputText.slice(0, 500);
}

if (updated.length > 0) {
  mergedFacts.updated_fields_last_turn = updated;
  mergedFacts.last_captured_at = nowIso;
}

const resetNotifyRequested = Boolean(outbound.reset_notify_requested);
let teamNotified = parseBool(mergedFacts.team_notified);
if (resetNotifyRequested) {
  mergedFacts.team_notified = false;
  mergedFacts.team_notified_at = '';
  mergedFacts.lead_notify_last_at = '';
  mergedFacts.lead_notify_cooldown_until = '';
  teamNotified = false;
}

const leadNotifyLastAt = String(mergedFacts.lead_notify_last_at || '').trim();
const leadNotifyLastMs = leadNotifyLastAt ? new Date(leadNotifyLastAt).getTime() : 0;
const cooldownUntilMs = leadNotifyLastMs ? (leadNotifyLastMs + cooldownMs) : 0;
const cooldownActive = leadNotifyLastMs > 0 && nowMs < cooldownUntilMs;

const leadRelevantFields = new Set(['customer_email', 'vehicle_brand_model', 'vehicle_description', 'vehicle_url', 'vehicle_year', 'vehicle_km', 'customer_phone', 'customer_name']);
const hasLeadRelevantUpdate = updated.some(f => leadRelevantFields.has(f));

let shouldNotify = false;
let notifyReason = '';
if (stage !== 'listo_para_cierre') notifyReason = 'stage_not_ready';
else if (isHuman) notifyReason = 'human_handoff';
else if (cooldownActive) notifyReason = 'cooldown_active';
else if (!teamNotified) {
  shouldNotify = true;
  notifyReason = 'ready_first_notification';
} else if (hasLeadRelevantUpdate) {
  shouldNotify = true;
  notifyReason = 'ready_with_new_data';
} else notifyReason = 'already_notified_no_change';

if (shouldNotify) {
  mergedFacts.team_notified = true;
  mergedFacts.team_notified_at = nowIso;
  mergedFacts.lead_notify_last_at = nowIso;
  mergedFacts.lead_notify_cooldown_until = new Date(nowMs + cooldownMs).toISOString();
  mergedFacts.lead_notify_count = Number(mergedFacts.lead_notify_count || 0) + 1;
}

const securityLevel = String(outbound.security_flags?.level || 'none');
let responseMode = 'normal';
if (isHuman) responseMode = 'handoff';
else if (postCloseLock === 'on' && userSignal === 'phatic') responseMode = 'post_cierre_phatic';
else if (postCloseLock === 'on') responseMode = 'post_cierre';
else if (securityLevel === 'high' || securityLevel === 'medium') responseMode = 'security_guard';

mergedFacts.last_agent_mode = responseMode;
mergedFacts.conversation_version = 8;

mergedFacts.notification_debug = {
  at: nowIso,
  parse_status: parseStatus,
  stage,
  contact_state: mergedFacts.contact_state,
  response_style: mergedFacts.response_style,
  precision_mode: mergedFacts.precision_mode,
  post_close_lock: mergedFacts.post_close_lock,
  tone_mode: mergedFacts.tone_mode,
  user_signal: userSignal,
  response_mode: responseMode,
  security_level: securityLevel,
  should_notify: shouldNotify,
  reason: notifyReason,
  cooldown_minutes: COOLDOWN_MINUTES,
  cooldown_active: cooldownActive,
  has_lead_relevant_update: hasLeadRelevantUpdate,
  repeat_count: Number(mergedFacts.assistant_repeat_count || 0)
};

const memoryName = String(mergedFacts.customer_name || existing.name || '').trim();
const memoryLastIntent = String(
  mergedFacts.last_user_intent
  || mergedFacts.customer_intent
  || outbound.message_text
  || existing.last_intent
  || ''
).trim();

return [{
  json: {
    ...outbound,
    memory_key_facts: mergedFacts,
    memory_name: memoryName,
    memory_last_intent: memoryLastIntent,
    should_notify: shouldNotify,
    notify_reason: notifyReason,
    notify_debug: mergedFacts.notification_debug
  }
}];

const item = $input.first().json;
const messageType = String(item.message_type || 'unknown');
const waId = item.wa_id;

let output = '';

switch (messageType) {
  case 'image':
  case 'video':
    output = 'Recibi tu archivo! Por ahora solo puedo leer mensajes de texto. Me escribes los datos del auto que quieres vender? Marca, modelo, ano y kilometraje. Si tienes el link de publicacion, con eso basta.';
    break;
  case 'audio':
    output = 'Recibi tu audio, pero por ahora solo puedo leer mensajes de texto. Me los escribes por favor?';
    break;
  case 'document':
    output = 'Recibi tu documento! Por ahora solo proceso mensajes de texto. Me escribes los datos del auto? Marca, modelo, ano y km.';
    break;
  default:
    output = '';
}

return [{ json: { wa_id: waId, output: output } }];

const item = $input.first().json;
const kf = item.memory_key_facts || {};
const notifyPhone = $('Normalizar Entrada').item.json.notify_phone || '+56975400946';

const lines = ['*Lead caliente*', ''];

if (kf.customer_name) lines.push('Nombre: ' + kf.customer_name);
if (kf.customer_phone) lines.push('Tel: ' + kf.customer_phone);
if (kf.customer_email) lines.push('Correo: ' + kf.customer_email);

if (kf.vehicle_url) {
  lines.push('Link auto: ' + kf.vehicle_url);
} else {
  const autoParts = [];
  const brandModel = String(kf.vehicle_brand_model || '').trim();
  const year = String(kf.vehicle_year || '').trim();
  const hasYearInsideBrand = Boolean(brandModel && year && new RegExp('\\b' + year + '\\b').test(brandModel));
  if (brandModel) autoParts.push(brandModel);
  if (year && !hasYearInsideBrand) autoParts.push(year);

  const kmRaw = String(kf.vehicle_km || '').trim();
  if (kmRaw) {
    const kmNum = parseInt(kmRaw.replace(/[^0-9]/g, ''), 10);
    const yearNum = parseInt(String(kf.vehicle_year || '').replace(/[^0-9]/g, ''), 10);
    if (Number.isFinite(kmNum) && kmNum >= 1000 && kmNum <= 500000 && kmNum !== yearNum && !(kmNum >= 1800 && kmNum <= 2099)) {
      autoParts.push(kmNum.toLocaleString('es-CL') + ' km');
    } else if (kmRaw && !/^\d{4}$/.test(kmRaw.replace(/[^0-9]/g, ''))) {
      autoParts.push(kmRaw);
    }
  }

  if (autoParts.length > 0) lines.push('Auto: ' + autoParts.join(' | '));
  if (kf.vehicle_description && !kf.vehicle_brand_model) lines.push('Info auto: ' + String(kf.vehicle_description).slice(0, 120));
}

if (kf.customer_intent) lines.push('Intencion: ' + kf.customer_intent);
if (kf.funnel_stage) lines.push('Funnel: ' + kf.funnel_stage);
if (kf.notification_debug?.reason) lines.push('Motivo trigger: ' + kf.notification_debug.reason);

lines.push('');
lines.push('wa.me/' + (item.wa_id || ''));

return [{ json: { notify_phone: notifyPhone, notification_text: lines.join('\n') } }];
